SVG_TAGS = {x.lower():x for x in '''altGlyph altGlyphDef altGlyphItem animateColor animateMotion animateTransform clipPath feBlend feColorMatrix feComponentTransfer feComposite feConvolveMatrix feDiffuseLighting feDisplacementMap feDistantLight feDropShadow feFlood feFuncA feFuncB feFuncG feFuncR feGaussianBlur feImage feMerge feMergeNode feMorphology feOffset fePointLight feSpecularLighting feSpotLight feTile feTurbulence foreignObject glyphRef linearGradient radialGradient textPath'''.split()}
SVG_ATTRS = {x.lower():x for x in '''attributeName attributeType baseFrequency baseProfile calcMode clipPathUnits diffuseConstant edgeMode filterUnits glyphRef gradientTransform gradientUnits kernelMatrix kernelUnitLength keyPoints keySplines keyTimes lengthAdjust limitingConeAngle markerHeight markerUnits markerWidth maskContentUnits maskUnits numOctaves pathLength patternContentUnits patternTransform patternUnits pointsAtX pointsAtY pointsAtZ preserveAlpha preserveAspectRatio primitiveUnits refX refY repeatCount repeatDur requiredExtensions requiredFeatures specularConstant specularExponent spreadMethod startOffset stdDeviation stitchTiles surfaceScale systemLanguage tableValues targetX targetY textLength viewBox viewTarget xChannelSelector yChannelSelector zoomAndPan'''.split()}

class Node:
    __slots__ = ('kind','tag','ns','attrs','children','parent','data')
    def __init__(self, kind='element', tag='', attrs=None, ns=HTML, data=''):
        self.kind, self.tag, self.ns = kind, tag, ns
        self.attrs = attrs if attrs is not None else {}
        self.children = []
        self.parent = None
        self.data = data
    def append(self, node):
        if node.parent is not None:
            node.parent.children.remove(node)
        node.parent = self
        self.children.append(node)
        return node
    def detach(self):
        if self.parent is not None:
            self.parent.children.remove(self)
            self.parent = None
    def get(self, name, default=None):
        return self.attrs.get(('', name), default)
    def elements(self, include=True):
        if include and self.kind == 'element':
            yield self
        for ch in self.children:
            if ch.kind == 'element':
                yield from ch.elements()
    def texts(self):
        for ch in self.children:
            if ch.kind == 'text':
                yield ch.data
            else:
                yield from ch.texts()
    def clone(self):
        return Node(tag=self.tag, attrs=self.attrs.copy(), ns=self.ns)

# Character references are consumed by longest matching name.  Attribute
# references without semicolons have an additional ambiguity rule.
NAMED = entities.html5
MAX_ENTITY = max(map(len, NAMED))
WINDOWS = {0x80:0x20ac,0x82:0x201a,0x83:0x192,0x84:0x201e,0x85:0x2026,0x86:0x2020,0x87:0x2021,0x88:0x2a6,0x89:0x2030,0x8a:0x160,0x8b:0x2039,0x8c:0x152,0x8e:0x17d,0x91:0x2018,0x92:0x2019,0x93:0x201c,0x94:0x201d,0x95:0x2022,0x96:0x2013,0x97:0x2014,0x98:0x2ca,0x99:0x2122,0x9a:0x161,0x9b:0x203a,0x9c:0x153,0x9f:0x178,0x9e:0x17e}
# Correct Windows-1252 spacing accents.
WINDOWS[0x88], WINDOWS[0x98] = 0x2c6, 0x2dc

def unescape(s, attr=False):
    if '&' not in s:
        return s
    out=[]; i=0
    while i < len(s):
        j=s.find('&',i)
        if j<0:
            out.append(s[i:]);break
        out.append(s[i:j]); i=j+1
        m=re.match(r'#(x[0-9a-f]+|[0-9]+);?',s[i:],re.I)
        if m:
            digits=m.group(1)
            try: cp=int(digits[1:],16) if digits[0].lower()=='x' else int(digits)
            except ValueError: cp=0
            if cp==0 or cp>0x10dffff or 0xd800<=cp<=0xdfff or cp>0x10ffff:
                cp=0xfffd
            cp=WINDOWS.get(cp,cp)
            out.append(chr(cp));i+=len(m.group());continue
        found=False
        for n in range(min(MAX_ENTITY,len(s)-i),0,-1):
            key=s[i:i+n]
            if key in NAMED:
                if attr and not key.endswith(';') and i+n<len(s) and (s[i+n] in '=0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ'):
                    break
                out.append(NAMED[key]);i+=n;found=True;break
        if not found: out.append('&')
    return ''.join(out)

def lower(s):
    return s.translate(str.maketrans('ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz'))

class Tokenizer:
    def __init__(self, source):
        self.s=source.replace('\r\n','\n').replace('\r','\n')
