            j=i+m.start() if m else n
            if j>i:
                self.i=j
                data=s[i:j].replace('\x00','\ufffd')
                return ('text',unescape(data) if rc else data)
            self.raw=None
        c=s[i]
        if c!='<':
            j=s.find('<',i)
            if j<0:j=n
            self.i=j
            return ('text',unescape(s[i:j]))
        if s.startswith('<!--',i):
            start=i+4
            if s.startswith('>', start):
                self.i=start+1;return ('comment','')
            if s.startswith('->',start):
                self.i=start+2;return ('comment','')
            m=re.search(r'--!?>',s[start:])
            j=start+m.start() if m else n
            self.i=start+m.end() if m else n
            return ('comment',s[start:j].replace('\0','\ufffd'))
        if s[i:i+9].lower()=='<!doctype':
            j=s.find('>',i+9)
            self.i=j+1 if j>=0 else n
            return ('doctype',s[i+9:j if j>=0 else n].strip())
        if foreign and s.startswith('<![CDATA[',i):
            j=s.find(']]>',i+9)
            self.i=j+3 if j>=0 else n
            return ('text',s[i+9:j if j>=0 else n])
        if s.startswith('<!',i) or s.startswith('<?',i):
            j=s.find('>',i+2)
            self.i=j+1 if j>=0 else n
            return ('comment',s[i+2 if s[i+1]=='!' else i+1:j if j>=0 else n].replace('\0','\ufffd'))
