        attrs={}; closed=False; slash=False
        while p<n:
            while p<n and s[p] in SPACE:p+=1
            if p>=n:break
            if s[p]=='>':p+=1;closed=True;break
            if s[p]=='/':
                p+=1
                if p<n and s[p]=='>':p+=1;closed=True;slash=True;break
                continue
            a=p
            if s[p]=='=':p+=1
            while p<n and s[p] not in SPACE+'/=>':p+=1
            name=lower(s[a:p].replace('\0','\ufffd'))
            while p<n and s[p] in SPACE:p+=1
            val=''
            if p<n and s[p]=='=':
                p+=1
                while p<n and s[p] in SPACE:p+=1
                if p<n and s[p] in '\"\'':
                    q=s[p];p+=1;a=p
                    while p<n and s[p]!=q:p+=1
                    val=s[a:p]
                    if p<n:p+=1
                else:
                    a=p
