"""URL resolution for the href output mode."""
import re
import ipaddress
from urllib.parse import urlsplit, urlunsplit, quote, unquote

SPECIAL = {'http':80,'https':443,'ftp':21,'ws':80,'wss':443,'file':None}
SCHEME = re.compile(r'^([A-Za-z][A-Za-z0-9+.-]*):')

class BadURL(ValueError):pass

def encode(s,kind,special=False):
    chars={'path':' "#<>?`{}','query':' "#<>','fragment':' "<>`','opaque':''}[kind]
    if kind=='query' and special:chars+="'"
    out=[]
    for c in s:
        if ord(c)<=0x20 or ord(c)>126 or c in chars:
            out.extend('%%%02X'%b for b in c.encode('utf-8'))
        else:out.append(c)
    return ''.join(out)

def clean(s):return s.strip(''.join(chr(i) for i in range(33))).replace('\t','').replace('\r','').replace('\n','')

def ipv4(host):
    parts=host.split('.')
    if parts[-1]=='':parts.pop()
    if not parts:return host
    def number(x):
        if x.lower().startswith('0x'):
            return int(x[2:] or '0',16)
        if len(x)>1 and x.startswith('0'):return int(x[1:] or '0',8)
        return int(x,10)
    try:number(parts[-1]);numeric=True
    except ValueError:numeric=bool(re.fullmatch(r'[0-9]+',parts[-1]))
    if not numeric:return host
    if len(parts)>4:raise BadURL()
    try:nums=[number(p) for p in parts]
    except ValueError:raise BadURL()
    if any(n>255 or n<0 for n in nums[:-1]) or nums[-1]<0 or nums[-1]>=256**(5-len(nums)):raise BadURL()
    v=nums[-1]
    for i,n in enumerate(nums[:-1]):v+=n*256**(3-i)
    return str(ipaddress.IPv4Address(v))

def authority(netloc,scheme):
    special=scheme in SPECIAL
    auth=''
    if '@' in netloc:
        user,netloc=netloc.rsplit('@',1)
        if not netloc:raise BadURL()
        u,sep,p=user.partition(':')
        safe="!$&'()*+,-._~%"
        auth=quote(u,safe=safe)
        if sep and p:auth+=':'+quote(p,safe=safe)
        if auth:auth+='@'
    if netloc.startswith('['):
        j=netloc.find(']')
        if j<0:raise BadURL()
        try:host='['+ipaddress.IPv6Address(netloc[1:j]).compressed+']'
        except ValueError:raise BadURL()
        rest=netloc[j+1:]
        if rest and not rest.startswith(':'):raise BadURL()
        port=rest[1:] if rest else ''
    else:
        if ':' in netloc:host,port=netloc.rsplit(':',1)
        else:host,port=netloc,''
        if special:
            try:host=unquote(host,errors='strict')
            except (UnicodeError,ValueError):raise BadURL()
            if any(ord(c)<=32 or c in '#%/:<>?@[\\]^|' for c in host):raise BadURL()
            try:host=host.encode('idna').decode('ascii').lower()
            except UnicodeError:raise BadURL()
            if host:host=ipv4(host)
            if scheme=='file' and host=='localhost':host=''
        else:
            if any(ord(c)<=32 or c in '#/:<>?@[\\]^|' for c in host):raise BadURL()
            host=encode(host,'opaque')
