    segments=path.split('/');out=[]
    for i,seg in enumerate(segments):
        val=seg.lower().replace('%2e','.')
        if val=='.':
            if i==len(segments)-1:out.append('')
        elif val=='..':
            if out and not (len(out)==1 and out[0]==''):out.pop()
