        self.scheme=scheme;self.netloc=netloc;self.path=path;self.query=query;self.fragment=fragment
        self.opaque=opaque;self.authority_present=authority_present
    def __str__(self):
        return self.scheme+':'+('//'+self.netloc if self.authority_present else '')+self.path+('?' + self.query if self.query is not None else '')+('#'+self.fragment if self.fragment is not None else '')

