    if fragment is not None:fragment=encode(fragment,'fragment',special)
    return URL(scheme,netloc,path,query,fragment,opaque,has_auth)

def parse(s):
    try:return absolute(s)
    except (BadURL,ValueError,UnicodeError,OverflowError):return None

def join(base,s):
    original=str(base)
    try:
        s=clean(s);m=SCHEME.match(s)
        if m:
            scheme=m[1].lower();rest=s[len(m[0]):]
            if scheme!=base.scheme or scheme not in SPECIAL or rest.startswith('//') or rest.startswith('\\\\'):return str(absolute(s))
            s=rest
        if base.opaque:
            if not s.startswith('#'):return original
            return str(URL(base.scheme,base.netloc,base.path,base.query,encode(s[1:],'fragment'),True,False))
        if base.scheme in SPECIAL:s=s.replace('\\','/')
        if s.startswith('//'):return str(absolute(base.scheme+':'+s))
        path,query,fragment=split_tail(s)
        if path:
            if not path.startswith('/'):
                path=base.path[:base.path.rfind('/')+1]+path
                if base.authority_present and not path.startswith('/'):path='/'+path
