        else:
            path=base.path
            if query is None:query=base.query
        if query is not None:query=encode(query,'query',base.scheme in SPECIAL)
        if fragment is not None:fragment=encode(fragment,'fragment',base.scheme in SPECIAL)
        return str(URL(base.scheme,base.netloc,path,query,fragment,False,base.authority_present))
    except (BadURL,ValueError,UnicodeError,OverflowError):return original
