OPTIONS={'attribute':'<attribute>','base':'<base>','filename':'<FILE>','output':'<FILE>','remove-nodes':'<SELECTOR>...'}
FLAGS={'detect-base','help','ignore-whitespace','pretty','text','version'}
PROGRAM=os.path.basename(sys.argv[0])
if PROGRAM=='main.py':PROGRAM='executable'

def option_display(name):return '--'+name+(' '+OPTIONS[name] if name in OPTIONS else '')

def usage(seen):
    opts=sorted(set(seen)-{'help','version'})
    return PROGRAM+' '+(' '.join(option_display(x) for x in opts) if opts else GENERAL_USAGE)

def cli_error(msg,seen):
    sys.stderr.write('error: '+msg+'\n\nUSAGE:\n    '+usage(seen)+'\n\nFor more information try --help\n')
    raise SystemExit(1)

def jaro(a,b):
    if a==b:return 1.0
    if not a or not b:return 0.0
    d=max(len(a),len(b))//2-1
    ma=[False]*len(a);mb=[False]*len(b)
    for i,c in enumerate(a):
        for j in range(max(0,i-d),min(len(b),i+d+1)):
            if not mb[j] and c==b[j]:ma[i]=True;mb[j]=True;break
    m=sum(ma)
    if not m:return 0.0
    aa=[c for i,c in enumerate(a) if ma[i]];bb=[c for i,c in enumerate(b) if mb[i]]
    t=sum(x!=y for x,y in zip(aa,bb))/2
    score=(m/len(a)+m/len(b)+(m-t)/m)/3
    prefix=0
    for x,y in zip(a,b):
        if x!=y or prefix==4:break
        prefix+=1
    return score+(prefix*.1*(1-score) if score>.7 else 0)

