    msg="Found argument '"+arg+"' which wasn't expected, or isn't valid in this context"
    if arg.startswith('--'):
        scores=[(jaro(arg[2:],x),x) for x in sorted(FLAGS|set(OPTIONS))]
        score,suggestion=max(scores)
        if score>.8:
            msg+='\n\tDid you mean \x1b[32m--\x1b[0m\x1b[32m'+suggestion+'\x1b[0m?'
            seen=seen+[suggestion]
