    def add(name,value=None):
        if name=='help':sys.stdout.write(HELP.format(program=PROGRAM));raise SystemExit(0)
        if name=='version':sys.stdout.write('htmlq 0.4.0\n');raise SystemExit(0)
        if name in seen and name!='remove-nodes':
            cli_error("The argument '"+option_display(name)+"' was provided more than once, but cannot be used multiple times",seen)
        seen.append(name)
