        elif name=='remove-nodes':result[name].extend(value.split(','))
        else:result[name]=value
    while i<len(argv):
        arg=argv[i];i+=1
        if end:pos.append(arg);continue
        if arg=='--':end=True;continue
        if arg.startswith('--'):
