                if char not in SHORT:unknown('-'+char,seen)
                name=SHORT[char]
                if name in FLAGS:add(name);continue
                if j<len(arg):
                    value=arg[j:]
                    if value.startswith('='):value=value[1:]
                    j=len(arg)
                elif i<len(argv) and (not argv[i].startswith('-') or argv[i]=='-'):
                    value=argv[i];i+=1
                else:value=None
