def panic(line,message):
    sys.stderr.write("\nthread 'main' ("+str(os.getpid())+") panicked at src/main.rs:"+line+':\n'+message+'\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n')
    raise SystemExit(101)

def os_error(e):
    kinds={errno.ENOENT:'NotFound',errno.EACCES:'PermissionDenied',errno.EPERM:'PermissionDenied',errno.EISDIR:'IsADirectory',errno.ENOTDIR:'NotADirectory',errno.EPIPE:'BrokenPipe',errno.ENOSPC:'StorageFull',errno.EINVAL:'InvalidInput',errno.EEXIST:'AlreadyExists',errno.ELOOP:'FilesystemLoop'}
