        except OSError as e:panic('196:37','should have opened input file: '+os_error(e))
    if opts.get('output','-')!='-':
        try:outfile=open(opts['output'],'wb')
        except OSError as e:panic('202:39','should have created output file: '+os_error(e))
    try:source=(infile or sys.stdin.buffer).read().decode('utf-8','replace')
