        except (cssquery.SelectorError,ValueError,RecursionError):pass
    base=urls.parse(opts.get('base',''))
    if opts.get('detect-base'):
        node=next((n for n in root.elements() if n.tag=='base'),None)
        if node is not None:
            detected=urls.parse(node.get('href',''))
            if detected:base=detected
    out=[]
    for node in selected:
        if any(cssquery.matches(desc,query) for query in removes for desc in node.elements()):continue
        if 'attribute' in opts:
            value=node.get(opts['attribute'])
            if value is None:continue
            if opts['attribute']=='href' and node.tag in ('a','area','link') and base is not None:value=urls.join(base,value)
        elif opts.get('text'):value=render.text(node,opts.get('ignore-whitespace',False))
        else:value=render.serialize(node,opts.get('pretty',False))
        out.append(value+'\n')
    data=''.join(out).encode('utf-8')
    try:
