    return PROGRAM+' '+(' '.join(option_display(x) for x in opts) if opts else GENERAL_USAGE)

def cli_error(msg,seen):
    sys.stderr.write('error: '+msg+'\n\nUSAGE:\n    '+usage(seen)+'\n\nFor more information try --help\n')
    raise SystemExit(1)

def jaro(a,b):
    if a==b:return 1.0
    if not a or not b:return 0.0
    d=max(len(a),len(b))//2-1
