            if not mb[j] and c==b[j]:ma[i]=True;mb[j]=True;break
    m=sum(ma)
    if not m:return 0.0
    aa=[c for i,c in enumerate(a) if ma[i]];bb=[c for i,c in enumerate(b) if mb[i]]
